import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Narrows a customer list. A customer matches when it satisfies both parts.
 *
 * @param name     text to find in the customer's first or last name; see {@link #matches(Customer)}
 * @param statuses statuses to keep; empty keeps every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICAL_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = Set.copyOf(statuses);
    }

    /**
     * Whether a customer passes this filter.
     *
     * <p>The name is split on whitespace into terms, and every term must appear as a
     * substring of the first name or of the last name. Case and accents are ignored, so
     * {@code makinen} matches {@code Mäkinen}. An empty name matches everyone.
     */
    public boolean matches(Customer customer) {
        return matchesName(customer) && (statuses.isEmpty() || statuses.contains(customer.status()));
    }

    private boolean matchesName(Customer customer) {
        String firstName = fold(customer.firstName());
        String lastName = fold(customer.lastName());
        for (String term : nameTerms()) {
            if (!firstName.contains(term) && !lastName.contains(term)) {
                return false;
            }
        }
        return true;
    }

    private List<String> nameTerms() {
        String folded = fold(name).strip();
        return folded.isEmpty() ? List.of() : List.of(WHITESPACE.split(folded));
    }

    /** Lower-cases text and strips accents, so {@code Mäkinen} folds to {@code makinen}. */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return DIACRITICAL_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
