import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import org.junit.jupiter.api.Test;

class CustomerFilterTest {

    private static final Customer ADA = new Customer(
            1000, "Ada", "Aaltonen", "ada.aaltonen.1000@example.com", "Finland", CustomerStatus.ACTIVE);
    private static final Customer JARNO = new Customer(
            1009, "Jarno", "Mäkinen", "jarno.makinen.1009@example.com", "Netherlands", CustomerStatus.PENDING);
    private static final Customer JOSEPHINE = new Customer(
            1035, "Joséphine", "Aaltonen", "josefine.aaltonen.1035@example.com", "Portugal", CustomerStatus.CLOSED);

    @Test
    void emptyFilterMatchesEveryone() {
        assertTrue(CustomerFilter.NONE.matches(ADA));
        assertTrue(new CustomerFilter("   ", Set.of()).matches(JARNO));
    }

    @Test
    void everyTermMustMatchFirstOrLastName() {
        assertTrue(new CustomerFilter("ada aal", Set.of()).matches(ADA));
        assertTrue(new CustomerFilter("aal ada", Set.of()).matches(ADA));
        assertFalse(new CustomerFilter("ada virtanen", Set.of()).matches(ADA));
    }

    @Test
    void whitespaceIsNotSignificant() {
        assertTrue(new CustomerFilter("  ada \t  aal  ", Set.of()).matches(ADA));
    }

    @Test
    void caseIsIgnored() {
        assertTrue(new CustomerFilter("MAKINEN", Set.of()).matches(JARNO));
    }

    @Test
    void accentsAreIgnoredInBothDirections() {
        assertTrue(new CustomerFilter("makinen", Set.of()).matches(JARNO));
        assertTrue(new CustomerFilter("mäkinen", Set.of()).matches(JARNO));
        assertTrue(new CustomerFilter("josephine", Set.of()).matches(JOSEPHINE));
        assertTrue(new CustomerFilter("Joséphine", Set.of()).matches(JOSEPHINE));
    }

    @Test
    void statusFilterKeepsOnlySelectedStatuses() {
        assertTrue(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)).matches(ADA));
        assertFalse(new CustomerFilter("", Set.of(CustomerStatus.PENDING)).matches(ADA));
        assertTrue(new CustomerFilter("", Set.of(CustomerStatus.PENDING, CustomerStatus.CLOSED))
                .matches(JOSEPHINE));
    }

    @Test
    void bothFiltersMustPass() {
        assertTrue(new CustomerFilter("ada", Set.of(CustomerStatus.ACTIVE)).matches(ADA));
        assertFalse(new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED)).matches(ADA));
        assertFalse(new CustomerFilter("jarno", Set.of(CustomerStatus.ACTIVE)).matches(ADA));
    }
}
